import heapq

def shortest_path(edges, start, end):
    """
    Find the shortest path from start to end node in a directed graph.

    Args:
        edges: List of tuples (from_node, to_node, weight)
        start: Starting node (string or hashable)
        end: Ending node (string or hashable)

    Returns:
        Tuple (distance, path) where distance is total edge weight and 
        path is list of nodes from start to end.
        If no path exists, returns (None, None).

    Raises:
        ValueError: If any edge has a negative weight.
    """

    # If start and end are the same node
    if start == end:
        return (0, [start])

    # Build adjacency list from edges
    graph = {}
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weights are not allowed")

        if from_node not in graph:
            graph[from_node] = {}
        if to_node in graph[from_node]:
            graph[from_node][to_node] = min(graph[from_node][to_node], weight)
        else:
            graph[from_node][to_node] = weight

    # If either start or end node does not exist, no path possible
    if start not in graph or end not in graph:
        return (None, None)

    # Dijkstra's algorithm
    pq = [(0, start)]           # Priority queue: (distance, node)
    dist = {start: 0}          # Minimum distance to each node
    parent = {}                # Parent pointer for path reconstruction
    visited = set()            # Track visited nodes

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        if current_node in visited:
            continue

        visited.add(current_node)

        # Early exit if we reach the target
        if current_node == end:
            break

        # Explore neighbors
        if current_node in graph:
            for neighbor, weight in graph[current_node].items():
                new_dist = current_dist + weight

                if neighbor not in dist or new_dist < dist[neighbor]:
                    dist[neighbor] = new_dist
                    parent[neighbor] = current_node
                    heapq.heappush(pq, (new_dist, neighbor))

    # If end node was never reached
    if end not in dist:
        return (None, None)

    # Reconstruct path from end to start using parent pointers
    path = []
    node = end
    while node is not None:
        path.append(node)
        node = parent.get(node)

    path.reverse()  # Path should be from start to end

    return (dist[end], path)
